import backtrader as bt


class SentimentDonchianStrategy(bt.Strategy):
    params = (
        ('donchian_period', 20),
        ('atr_period', 14),
        ('sentiment_sma_period', 20),
        ('sentiment_multiplier', 2),
        ('base_size', 1),
    )

    def __init__(self):
        self.donchian_upper = bt.indicators.Highest(
            self.data.high, period=self.p.donchian_period
        )
        self.donchian_lower = bt.indicators.Lowest(
            self.data.low, period=self.p.donchian_period
        )
        self.atr = bt.indicators.ATR(self.data, period=self.p.atr_period)

        if len(self.datas) > 1:
            self.sentiment = self.datas[1].close
        else:
            self.sentiment = self.data.close * float('nan')
        self.sentiment_sma20 = bt.indicators.SMA(
            self.sentiment, period=self.p.sentiment_sma_period
        )

        self.upper_cross = bt.indicators.CrossOver(
            self.data.close, self.donchian_upper
        )
        self.lower_cross = bt.indicators.CrossOver(
            self.data.close, self.donchian_lower
        )

        self.order = None
        self.stop_order = None
        self.entry_atr = None

    def next(self):
        if self.order is not None:
            return

        sentiment = self.sentiment[0]
        sentiment_sma20 = self.sentiment_sma20[0]
        long_signal = self.upper_cross[0] > 0 and sentiment > sentiment_sma20
        short_signal = self.lower_cross[0] < 0 and sentiment < sentiment_sma20

        if not self.position:
            if long_signal or short_signal:
                size_multiplier = 1 + self.p.sentiment_multiplier * abs(
                    (sentiment - sentiment_sma20)
                    / max(abs(sentiment_sma20), 1e-6)
                )
                position_size = self.p.base_size * size_multiplier
                self.entry_atr = self.atr[0]
                if long_signal:
                    self.order = self.buy(size=position_size)
                else:
                    self.order = self.sell(size=position_size)
        elif (self.position.size > 0 and short_signal) or (
            self.position.size < 0 and long_signal
        ):
            if self.stop_order is not None:
                self.cancel(self.stop_order)
            self.order = self.close()

    def notify_order(self, order):
        if order.status in (order.Submitted, order.Accepted):
            return

        if order is self.stop_order:
            if order.status in (
                order.Completed,
                order.Canceled,
                order.Margin,
                order.Rejected,
            ):
                self.stop_order = None
            return

        if order is self.order:
            if order.status == order.Completed and self.position:
                if self.position.size > 0:
                    stop_price = order.executed.price - (2 * self.entry_atr)
                    self.stop_order = self.sell(
                        exectype=bt.Order.Stop,
                        price=stop_price,
                        size=abs(self.position.size),
                    )
                else:
                    stop_price = order.executed.price + (2 * self.entry_atr)
                    self.stop_order = self.buy(
                        exectype=bt.Order.Stop,
                        price=stop_price,
                        size=abs(self.position.size),
                    )

            if order.status in (
                order.Completed,
                order.Canceled,
                order.Margin,
                order.Rejected,
            ):
                self.order = None
                self.entry_atr = None
